from .paths import TemplatesRecognizer
from .parser import TemplateParser
from .files import TemplateSerializer
from .facades import TemplatesProcessFacade
from .factory import (HeatTemplateFactory, ExtractorFactory)
from .templates import (Templates5G17, Templates5G17A, Templates5G18A,
                        TemplatesCache, TemplatesDispatcher, SingleTemplate,
                        HeatTemplate, Templates5G18A_RCP20, TemplatesAgent5g)


def extract_templates(addons, destination, variant, program='5G18A'):
    templ_cache = TemplatesCache()
    templ_dispatch = TemplatesDispatcher()
    recognizer = TemplatesRecognizer()
    extractor_factory = ExtractorFactory(templ_dispatch,
                                         templ_cache,
                                         recognizer,
                                         variant)
    templ_cache.define(TemplatesAgent5g, program=program)
    extractor = extractor_factory.create(addons)
    extractor.extract(archive=addons, destination=destination)


class heat_templates(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.templ_cache = TemplatesCache()
        self.templ_dispatch = TemplatesDispatcher()
        recognizer = TemplatesRecognizer()
        serializer = TemplateSerializer(SingleTemplate)
        factory = HeatTemplateFactory(serializer, HeatTemplate)
        self.extractor_factory = ExtractorFactory(self.templ_dispatch,
                                                  self.templ_cache,
                                                  recognizer)
        self.process_facade = TemplatesProcessFacade(recognizer,
                                                     serializer,
                                                     TemplateParser(),
                                                     factory)

    def define_templates(self, branch, **kwargs):
        """ It is alternative to such as `define_templates_5G17A`, one can do
        achieve the same effect if branch '5G17A' was specified as first
        argument of this method. Be aware that in this keyword user is
        responsible of giving correct named arguments, in our example with
        program 5G17A it would be 'option' and 'ueup' (look at mentioned
        keyword definition). """
        _cls = self.templ_dispatch.get_cls_by_program(branch)
        self.templ_cache.define(_cls, **kwargs)

    def define_templates_5G17(self, option):
        """ Define from which directory templates should be taken.

        :param option: str, possible values 'min' or 'max' """
        self.templ_cache.define(Templates5G17, option=option)

    def define_templates_5G17A(self, option, ueup):
        """ Define from which directory templates should be taken.

        :param option: str or int, number in range 1-2
        :param ueup: str or int, number in range 1-9 """
        self.templ_cache.define(Templates5G17A, option=option, ueup=ueup)

    def define_templates_5G18A(self, option, ueup):
        """ Define from which directory templates should be taken.

        :param option: str or int, number in range 1-2
        :param ueup: str or int, number in range 1-9 """
        self.templ_cache.define(Templates5G18A, option=option, ueup=ueup)

    def define_templates_5G18A_RCP20(self, standalone=False):
        self.templ_cache.define(Templates5G18A_RCP20, standalone=standalone)

    def extract_templates(self, addons, destination):
        """ Extract templates from Addons delivered with software.
        Templates for specific program should be defined before extraction,
        see for example `define_templates_5G17A`.

        :addons: path to Addons archive
        :destination: path to directory where extracted templates will be saved
        """
        extractor = self.extractor_factory.create(addons)
        extractor.extract(archive=addons, destination=destination)

    # TODO: this step should be also adapted to RCP2.0. first template
    # generation should be done, because then this step will probably also
    # change
    def process_templates(self, root_dir, destination):
        """ Load all templates from `root_dir`, then parse them and save new
        files in `destination`. It reads `yaml` and `env` files, looks at
        variables defined in `yaml` file and then cuts off redundant variables
        from `env` which does not affect examined yaml file. This process
        generates new `env` file which is equal or smaller to loaded one due to
        redundant variables reduction.

        :root_dir: path to directory where templates can be found
        :destination: path to directory where new templates will be saved

        """
        self.process_facade.process(root_dir=root_dir, destination=destination)
